from numpy.linalg import lstsq
cands={'1':np.ones_like(eps),'e':eps,'e2':eps**2,'le':np.log(eps),'T':T,'T2':T**2,'eT':eps*T,'lT':np.log(T),'T1e':T/eps,'1/e':1/eps,'sqrte':np.sqrt(eps),'e3':eps**3,'eT2':eps*T**2,'le*T':np.log(eps)*T}
names=list(cands)
def fit(ns):
    A=np.c_[[cands[n] for n in ns]].T
    c,*_=lstsq(A,sigma,rcond=None)
    r=sigma-A@c
    return np.mean(r**2)/np.var(sigma),c
import itertools
best=[]
for k in range(2,6):
    for ns in itertools.combinations(names,k):
        if '1' not in ns: continue
        v,c=fit(ns); best.append((v,ns))
best.sort(); 
